export const FONTS_LINK = "<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=IM+Fell+English:ital@0;1&family=IM+Fell+English+SC&display=swap\">";

export const BOARD_CSS = "/* Layout: an exhibition broadside. One measured column of laid paper, plates hung in a row,\n   rubricated labels, hairlines only where a printer would rule them. */\n&{\n  --paper:#ECEAE3; --paper-2:#E3E0D7; --mat:#F5F3EE;\n  --ink:#1D1A17; --ink-2:#5A544B; --rule:#C4BDB0;\n  --rubric:#9E2219;\n  --st-prima:#4B6A36; --st-nigredo:#1D1A17; --st-albedo:#8E8A80; --st-citrin:#A9821A; --st-rubedo:#9E2219;\n  --display:\"IM Fell English\",\"Iowan Old Style\",\"Palatino Linotype\",Palatino,Georgia,serif;\n  --display-sc:\"IM Fell English SC\",\"IM Fell English\",Georgia,serif;\n  --body:\"EB Garamond\",\"Iowan Old Style\",Garamond,Georgia,serif;\n}\n@media (prefers-color-scheme: dark){&{\n  --paper:#171511; --paper-2:#1F1C17; --mat:#2A261F;\n  --ink:#E7E1D4; --ink-2:#A79F90; --rule:#3D372E;\n  --rubric:#D9604F;\n  --st-prima:#8DAA72; --st-nigredo:#E7E1D4; --st-albedo:#BDB7AA; --st-citrin:#D9B24C; --st-rubedo:#D9604F;\n  color-scheme:dark}}\n\n&{background:var(--paper);color:var(--ink);font-family:var(--body);font-size:18px;line-height:1.5;\n  font-variant-numeric:oldstyle-nums;-webkit-font-smoothing:antialiased}\n.wrap{box-sizing:border-box;max-width:1140px;margin:0 auto;padding-block:40px 80px;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\na{color:inherit;text-decoration-color:var(--rubric);text-underline-offset:3px;text-decoration-thickness:1px}\na:hover{color:var(--rubric)}\na:focus-visible{outline:2px solid var(--rubric);outline-offset:2px}\nh1,h2,h3{font-family:var(--display);font-weight:400;text-wrap:balance;margin:0}\np{margin:0}\n.sc{font-family:var(--display-sc);letter-spacing:.06em}\n.rub{color:var(--rubric)}\n.muted{color:var(--ink-2)}\n.measure{max-width:64ch}\n\n/* masthead */\n.mast{text-align:center;display:grid;gap:14px;justify-items:center;padding-bottom:36px;border-bottom:3px double var(--ink)}\n.mast .eyebrow{font-family:var(--display-sc);letter-spacing:.14em;font-size:15px;color:var(--ink-2)}\n.mast h1{font-size:clamp(44px,8vw,92px);line-height:.95;letter-spacing:-.01em}\n.mast h1 em{display:block;font-size:.42em;font-style:italic;letter-spacing:0;margin-top:10px;color:var(--ink-2)}\n.mast .status{font-style:italic;color:var(--ink-2)}\n.mast .fact{font-family:var(--display);font-size:clamp(22px,3.2vw,30px);line-height:1.25;max-width:30ch;text-wrap:balance}\n.mast .fact b{font-weight:400;color:var(--rubric)}\n.mast .sub{font-size:16px;color:var(--ink-2);max-width:62ch}\n.lion{width:140px;aspect-ratio:1;border-radius:50%;overflow:hidden;border:1px solid var(--rule);background:var(--mat);max-width:100%}\n\n/* sections */\nsection{padding-block:56px 8px;display:grid;gap:22px}\n.sh{display:grid;gap:6px;border-top:1px solid var(--rule);padding-top:22px}\n.sh .label{font-family:var(--display-sc);letter-spacing:.14em;font-size:14px;color:var(--rubric)}\n.sh h2{font-size:clamp(30px,4.4vw,44px);line-height:1.05}\n.sh p{color:var(--ink-2);max-width:64ch}\n\n/* concepts */\n.concepts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}\n.concept{border:1px solid var(--rule);padding:22px 22px 24px;display:grid;gap:14px;align-content:start;background:var(--paper)}\n.concept.rec{border:2px solid var(--rubric);background:var(--paper-2)}\n.concept .tag{font-family:var(--display-sc);font-size:13px;letter-spacing:.14em;color:var(--ink-2);min-height:1.2em}\n.concept.rec .tag{color:var(--rubric)}\n.concept h3{font-size:30px;line-height:1.05}\n.concept .promise{font-style:italic;font-size:19px;line-height:1.4}\n.concept dl{margin:0;display:grid;gap:10px}\n.concept dt{font-family:var(--display-sc);font-size:13px;letter-spacing:.1em;color:var(--ink-2)}\n.concept dd{margin:0;font-size:16.5px;line-height:1.45}\n.verdict{border-left:3px solid var(--rubric);padding:4px 0 4px 18px;max-width:72ch;font-size:18px}\n\n/* ladder */\n.ladder-scroll{overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:6px}\n.ladder{display:grid;grid-template-columns:repeat(5,minmax(200px,1fr));gap:16px;min-width:0}\n.plate{display:grid;grid-template-rows:auto auto 1fr;gap:12px;scroll-snap-align:start}\n.plate figure{margin:0;background:var(--mat);border:1px solid var(--rule);padding:8px}\n.plate .pbox{display:block;position:relative;overflow:hidden;aspect-ratio:4/5;background:var(--paper-2)}\n.cr{position:absolute;left:50%;top:50%;height:100%;transform:translate(-50%,-50%);overflow:hidden;display:block}\n.cr img{position:absolute;max-width:none;display:block;filter:saturate(.9)}\n.lion{position:relative}\n.lion .cr.lionc{left:0;top:0;width:100%;height:100%;aspect-ratio:auto!important;transform:scale(1.35);transform-origin:40% 55%}\n.plate figcaption{font-size:13px;line-height:1.35;color:var(--ink-2);padding-top:6px}\n.plate .deg{display:grid;gap:2px;border-top:4px solid var(--st);padding-top:8px}\n.plate .deg .n{font-family:var(--display-sc);font-size:13px;letter-spacing:.12em;color:var(--ink-2)}\n.plate .deg h3{font-size:26px;line-height:1.05}\n.plate .deg .plain{font-style:italic;color:var(--ink-2)}\n.plate dl{margin:0;display:grid;gap:8px;font-size:15.5px;line-height:1.4}\n.plate dt{font-family:var(--display-sc);font-size:12px;letter-spacing:.12em;color:var(--ink-2)}\n.plate dd{margin:0}\n.plate blockquote{margin:4px 0 0;font-family:var(--display);font-style:italic;font-size:15.5px;line-height:1.35;border-top:1px solid var(--rule);padding-top:8px}\n.plate blockquote a{font-family:var(--body);font-style:normal;font-size:12.5px;color:var(--ink-2);display:block;margin-top:4px}\n.scrollhint{display:none;font-size:14px;color:var(--ink-2);font-style:italic}\n\n/* journey */\n.journey-scroll{overflow-x:auto;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink)}\n.journey{display:grid;grid-template-columns:150px repeat(6,minmax(150px,1fr));min-width:1060px}\n.journey > div{padding:12px 12px 14px;border-left:1px solid var(--rule);font-size:15px;line-height:1.4}\n.journey .t{font-family:var(--display-sc);letter-spacing:.1em;font-size:14px;border-bottom:1px solid var(--rule);position:relative;padding-top:20px}\n.journey .t::before{content:\"\";position:absolute;left:-5px;top:-5px;width:9px;height:9px;border-radius:50%;background:var(--ink)}\n.journey .who{border-left:0;font-family:var(--display);font-size:19px;line-height:1.2}\n.journey .who span{display:block;font-family:var(--body);font-size:13.5px;color:var(--ink-2);margin-top:6px}\n.journey .row2{border-top:1px solid var(--rule)}\n.journey b{font-weight:600}\n.journey .risk{display:block;margin-top:8px;color:var(--rubric);font-size:14px}\n.journey .risk::before{content:\"\\2715\\00a0\"}\n.journey .risk.hi{font-weight:600}\n.legend{display:flex;flex-wrap:wrap;gap:6px 22px;font-size:14px;color:var(--ink-2)}\n.legend .rub{font-weight:600}\n\n/* year */\n.year{display:grid;grid-template-columns:minmax(0,440px) minmax(0,1fr);gap:40px;align-items:start}\n.wheel svg{width:100%;height:auto;max-width:100%;display:block}\n.wheel .lbl{font-family:var(--display-sc);font-size:11px;letter-spacing:.08em;fill:var(--ink-2)}\n.wheel .ring{fill:none;stroke:var(--rule)}\n.wheel .wk{fill:var(--ink-2)}\n.wheel .mo{fill:var(--ink)}\n.wheel .se{fill:var(--paper);stroke:var(--ink);stroke-width:1.5}\n.wheel .cday{fill:var(--rubric)}\n.wheel .ctext{font-family:var(--display);font-size:15px;fill:var(--rubric)}\n.wheel .center{font-family:var(--display);font-size:22px;fill:var(--ink)}\n.wheel .center2{font-family:var(--body);font-style:italic;font-size:12px;fill:var(--ink-2)}\n.wheel .tick{stroke:var(--rule)}\n.rhythms{display:grid;gap:18px}\n.rhythm{display:grid;grid-template-columns:28px minmax(0,1fr);gap:12px;align-items:start}\n.rhythm svg{width:22px;height:22px;margin-top:4px}\n.rhythm h3{font-size:21px;line-height:1.15}\n.rhythm p{font-size:16px;color:var(--ink-2);margin-top:2px}\n.first-month{border:1px solid var(--rule);background:var(--paper-2);padding:22px;display:grid;gap:14px}\n.first-month h3{font-size:24px}\n.weeks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}\n.weeks div{display:grid;gap:6px;align-content:start;font-size:15.5px;line-height:1.4}\n.weeks .w{font-family:var(--display-sc);letter-spacing:.12em;font-size:13px;color:var(--rubric)}\n\n/* mechanics */\n.mechs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid var(--ink)}\n.mech{padding:18px 18px 22px;border-bottom:1px solid var(--rule);border-right:1px solid var(--rule);display:grid;gap:8px;align-content:start}\n.mech:nth-child(4n){border-right:0}\n.mech h3{font-size:21px;line-height:1.15}\n.mech p{font-size:15.5px;line-height:1.42}\n.mech .prec{font-size:14.5px;color:var(--ink-2)}\n.mech .prec i{color:var(--ink)}\n.mech .risk{font-size:14.5px;color:var(--rubric)}\n\n/* wild ideas */\n.wild{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}\n.idea{border-top:1px solid var(--ink);padding-top:8px;display:grid;gap:4px;align-content:start}\n.idea .num{font-family:var(--display);font-size:22px;color:var(--rubric);line-height:1;font-variant-numeric:lining-nums}\n.idea h3{font-size:17.5px;line-height:1.2;font-family:var(--body);font-weight:600}\n.idea p{font-size:14.5px;line-height:1.38;color:var(--ink-2)}\n.idea .rk{font-family:var(--display-sc);font-size:12px;letter-spacing:.12em;color:var(--rubric)}\n\n/* pre-mortem */\n.pm{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}\n.fail{display:grid;gap:10px;align-content:start;padding:18px 18px 20px;background:var(--paper-2);border:1px solid var(--rule)}\n.fail h3{font-size:22px;line-height:1.15}\n.fail p{font-size:15.5px;line-height:1.42}\n.fail .warn{border-top:1px dashed var(--rule);padding-top:10px;font-size:15px}\n.fail .warn span{font-family:var(--display-sc);letter-spacing:.1em;font-size:12.5px;color:var(--rubric);display:block}\n\n/* covenant broadside */\n.broadside{max-width:780px;margin:0 auto;width:100%;background:var(--mat);border:1px solid var(--rule);outline:1px solid var(--rule);outline-offset:6px;padding:44px clamp(18px,5vw,56px) 40px;display:grid;gap:22px}\n.broadside .head{text-align:center;display:grid;gap:6px}\n.broadside .head .sc{font-size:14px;letter-spacing:.2em;color:var(--ink-2)}\n.broadside .head h3{font-size:clamp(30px,5vw,44px);line-height:1.05}\n.broadside .head p{font-style:italic;color:var(--ink-2)}\n.art{display:grid;grid-template-columns:52px minmax(0,1fr);gap:4px 16px;padding-top:16px;border-top:1px solid var(--rule)}\n.art .num{font-family:var(--display);font-size:40px;line-height:.9;color:var(--rubric);grid-row:span 2;font-variant-numeric:lining-nums}\n.art .orig{font-family:var(--display);font-style:italic;font-size:19px;line-height:1.35}\n.art .ours{font-size:17px;line-height:1.45}\n.art.rev .orig{text-decoration:line-through;text-decoration-color:var(--rubric);text-decoration-thickness:2px;color:var(--ink-2)}\n.art.rev .ours{font-family:var(--display);font-size:22px;line-height:1.3;color:var(--rubric)}\n.broadside .foot{border-top:3px double var(--ink);padding-top:14px;font-size:15px;color:var(--ink-2);display:grid;gap:8px}\n.broadside .guard{font-size:16px;color:var(--ink)}\n\n/* decisions */\n.decisions{display:grid;gap:0;border-top:1px solid var(--ink)}\n.dec{display:grid;grid-template-columns:42px minmax(0,1.1fr) minmax(0,1fr);gap:8px 24px;padding:18px 0;border-bottom:1px solid var(--rule)}\n.dec .num{font-family:var(--display);font-size:28px;color:var(--rubric);line-height:1;font-variant-numeric:lining-nums}\n.dec h3{font-size:22px;line-height:1.2}\n.dec .def{font-size:16.5px;margin-top:6px}\n.dec .def b{font-family:var(--display-sc);font-weight:400;letter-spacing:.1em;font-size:13px;color:var(--rubric);margin-right:6px}\n.dec .alt{font-size:15.5px;color:var(--ink-2)}\n.dec .alt b{font-family:var(--display-sc);font-weight:400;letter-spacing:.1em;font-size:13px;margin-right:6px}\n\n.colophon{margin-top:56px;padding-top:18px;border-top:3px double var(--ink);font-size:14.5px;color:var(--ink-2);display:grid;gap:6px;text-align:center}\n\n@media (max-width:980px){\n  .mechs{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .mech:nth-child(4n){border-right:1px solid var(--rule)}\n  .mech:nth-child(2n){border-right:0}\n  .wild{grid-template-columns:repeat(3,minmax(0,1fr))}\n  .year{grid-template-columns:minmax(0,1fr)}\n  .wheel{max-width:460px;width:100%;margin:0 auto}\n  .weeks{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .pm{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n@media (max-width:820px){\n  .concepts{grid-template-columns:minmax(0,1fr)}\n  .ladder{grid-template-columns:repeat(5,minmax(230px,72vw))}\n  .scrollhint{display:block}\n}\n@media (max-width:560px){\n  body{font-size:17px}\n  .wrap{padding-block:24px 56px}\n  .mechs,.pm,.weeks{grid-template-columns:minmax(0,1fr)}\n  .mech{border-right:0!important}\n  .wild{grid-template-columns:minmax(0,1fr)}\n  .dec{grid-template-columns:32px minmax(0,1fr)}\n  .dec .alt{grid-column:2}\n  .art{grid-template-columns:36px minmax(0,1fr)}\n  .art .num{font-size:30px}\n}\n@media (prefers-reduced-motion:no-preference){\n  .plate .cr img{transition:filter .3s}\n  .plate figure:hover .cr img{filter:saturate(1.05)}\n}\n";

export const BOARD_HTML = "<div class=\"wrap\">\n\n<header class=\"mast\">\n  <div class=\"lion\"><span class=\"cr lionc\" style=\"aspect-ratio:1.010\"><img src=\"https://images.sourcelibrary.org/archived/69bd9cd86120d54bd037157c/178.jpg\" alt=\"Woodcut of the Green Lion devouring the Sun, Rosarium philosophorum 1550\" style=\"width:125.00%;height:151.52%;left:-12.50%;top:-32.88%\"></span></div>\n  <div class=\"eyebrow\">Source Library \u00b7 Volunteer order \u00b7 Design board</div>\n  <h1>The Invisible College<em>of Source Library</em></h1>\n  <p class=\"status\">Draft for discussion, 21 October 2026</p>\n  <p class=\"fact\"><b>1,438 people</b> have offered to help since July. None of them has had an answer.</p>\n  <p class=\"sub\">323 arrived in the last 30 days, about ten a day. About a quarter wrote in Spanish. This board sets out three ways to answer them as one community, the degrees and rites inside it, and the first month. The decisions are at the end.</p>\n</header>\n\n<!-- 2 -->\n<section id=\"concepts\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The three worlds</span><h2>What a member is, and what the work is called</h2>\n  <p>Each concept uses the same mechanics underneath: shifts, finds, quality gates, roles. Only the world changes.</p></div>\n  <div class=\"concepts\">\n    <article class=\"concept\">\n      <div class=\"tag\">Alchemical</div>\n      <h3>The Order of the Work</h3>\n      <p class=\"promise\">\u201cEvery old book here is raw matter; you help turn it into something people can read.\u201d</p>\n      <dl>\n        <dt>Signature ritual</dt><dd><b>The Projection.</b> When a book becomes readable, everyone who touched it is named on its page, with the colour of the stage each was at.</dd>\n        <dt>Draws</dt><dd>The core audience: Rosicrucian and Hermetic readers, Embassy visitors, readers of Jung, tarot and esotericism.</dd>\n        <dt>Puts off</dt><dd>Librarians, coders and academics wary of occultism; anyone who reads \u201cInner Circle\u201d as a cult.</dd>\n        <dt>Risk</dt><dd>The metaphor drifts into belief. One lead talking about spiritual transformation and the \u201cnobody is asked to believe anything\u201d rule is gone.</dd>\n      </dl>\n    </article>\n    <article class=\"concept\">\n      <div class=\"tag\">Monastic, plain</div>\n      <h3>The Scriptorium</h3>\n      <p class=\"promise\">\u201cCopy, check and correct old books, a page at a time, with others doing the same.\u201d</p>\n      <dl>\n        <dt>Signature ritual</dt><dd><b>The Colophon.</b> Each finished book closes with its correctors\u2019 names and the date, as scribes signed their work.</dd>\n        <dt>Draws</dt><dd>Librarians, Latinists, coders, academics, Wikipedia editors. Easiest to explain to a board or a funder.</dd>\n        <dt>Puts off</dt><dd>The people who came because of alchemy and Rosicrucianism and want the world to feel like the books.</dd>\n        <dt>Risk</dt><dd>No pull. It recruits well and retains poorly, and monastic framing implies obedience and silence.</dd>\n      </dl>\n    </article>\n    <article class=\"concept rec\">\n      <div class=\"tag\">Recommended \u00b7 Republic of Letters</div>\n      <h3>The Invisible College</h3>\n      <p class=\"promise\">\u201cJoin a correspondence of people reading the old books together, across countries; what you find, you write to the others.\u201d</p>\n      <dl>\n        <dt>Signature ritual</dt><dd><b>The Letter.</b> Any contribution can end in a short letter to the College. The best each month are bound into a public digest. Membership is conferred by a signed letter.</dd>\n        <dt>Draws</dt><dd>Spanish-speaking and international members, scholars, writers, Claude donors who like a weekly report, and readers who only want to receive the letters.</dd>\n        <dt>Puts off</dt><dd>People who want quick, game-like progress; people who do not write.</dd>\n        <dt>Risk</dt><dd>\u201cInvisible\u201d can sound secretive. Wherever the name first appears: <i>invisible because it has no building, not because it hides.</i></dd>\n      </dl>\n    </article>\n  </div>\n  <p class=\"verdict\"><b>The recommendation combines them.</b> The College is the world a newcomer meets: letters, a weekly Post, a correspondence in several languages. Inside it, the degrees keep their alchemical names with plain subtitles, because the stages describe what happens to a text and to a reader\u2019s skill. Tasks keep scriptorium words: page, shift, correction, colophon. The 1640s invisible college around Boyle and Hartlib grew partly out of the Rosicrucian hopes these books record.</p>\n</section>\n\n<!-- 3 -->\n<section id=\"ladder\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The ladder of degrees</span><h2>Five stages of the Work</h2>\n  <p>Gates harden as you climb: automatic, then measured review quality, then sponsorship, then a yearly rotating council of at most eight. Nothing is gated but roles; the library, the Discord and being heard are open to all. Plates and lines from the <a href=\"https://sourcelibrary.org/book/rosarium-philosophorum-secunda-pars-alchimiae-de-lapide-s-n-3\">Rosarium philosophorum</a> (Frankfurt, 1550) and the Splendor Solis (Aureum Vellus, 1598).</p></div>\n  <p class=\"scrollhint\">Swipe for all five plates \u2192</p>\n  <div class=\"ladder-scroll\">\n  <div class=\"ladder\">\n    <div class=\"plate\" style=\"--st:var(--st-prima)\">\n      <figure><span class=\"pbox\"><span class=\"cr\" style=\"aspect-ratio:1.010\"><img src=\"https://images.sourcelibrary.org/archived/69bd9cd86120d54bd037157c/178.jpg\" alt=\"The Green Lion devouring the Sun, woodcut\" loading=\"lazy\" style=\"width:125.00%;height:151.52%;left:-12.50%;top:-32.88%\"></span></span><figcaption>The Green Lion devouring the Sun. Rosarium, 1550, image 178.</figcaption></figure>\n      <div class=\"deg\"><span class=\"n\">Before the first degree</span><h3>Prima materia</h3><span class=\"plain\">Signed up</span></div>\n      <dl>\n        <dt>Enter by</dt><dd>The sign-up form. Automatic.</dd>\n        <dt>The rite</dt><dd>A welcome letter with one passage chosen in the language they wrote in, and one first task.</dd>\n        <blockquote>\u201c\u2026bodies are dissolved into the quicksilver of the Philosophers\u2026 and one new body is made.\u201d<a href=\"https://sourcelibrary.org/q/BhbmYbAoJrI07wWuH8k\">Rosarium, scan 34 \u2197</a></blockquote>\n      </dl>\n    </div>\n    <div class=\"plate\" style=\"--st:var(--st-nigredo)\">\n      <figure><span class=\"pbox\"><span class=\"cr\" style=\"aspect-ratio:0.833\"><img src=\"https://images.sourcelibrary.org/archived/69bd9cd86120d54bd037157c/68.jpg\" alt=\"Animae extractio: the soul leaves the body in the tomb, woodcut\" loading=\"lazy\" style=\"width:121.95%;height:123.46%;left:-12.20%;top:-6.05%\"></span></span><figcaption>Animae extractio. The soul leaves the body in the tomb. Rosarium, image 68.</figcaption></figure>\n      <div class=\"deg\"><span class=\"n\">First degree</span><h3>Nigredo</h3><span class=\"plain\">Apprentice</span></div>\n      <dl>\n        <dt>Enter by</dt><dd>A first completed task or review shift. Automatic.</dd>\n        <dt>The rite</dt><dd>Named in #welcome; an email with the page they touched, citable, listed as their \u201cfirst page\u201d.</dd>\n        <blockquote>\u201cEvery body, when it lacks a soul, is found to be shadowy and obscure.\u201d<a href=\"https://sourcelibrary.org/q/BhbmYbAoJrI07wWuH9J\">Rosarium, scan 69 \u2197</a></blockquote>\n      </dl>\n    </div>\n    <div class=\"plate\" style=\"--st:var(--st-albedo)\">\n      <figure><span class=\"pbox\"><span class=\"cr\" style=\"aspect-ratio:0.829\"><img src=\"https://images.sourcelibrary.org/archived/69bd9cd86120d54bd037157c/81.jpg\" alt=\"Ablutio: dew falls from clouds onto the body in the tomb, woodcut\" loading=\"lazy\" style=\"width:121.95%;height:125.00%;left:-9.76%;top:-7.38%\"></span></span><figcaption>Ablutio. Dew washes the body. Rosarium, image 81.</figcaption></figure>\n      <div class=\"deg\"><span class=\"n\">Second degree</span><h3>Albedo</h3><span class=\"plain\">Companion</span></div>\n      <dl>\n        <dt>Enter by</dt><dd>Measured review quality: their readings agree with a second reviewer over N pages. The number is published.</dd>\n        <dt>The rite</dt><dd>A letter from the track lead citing their figure. They choose a plate from the library as their seal.</dd>\n        <blockquote>\u201cTake the whiteness and cast away the blackness.\u201d<a href=\"https://sourcelibrary.org/q/BhbmYbAoJrI07wWuH9W\">Rosarium, scan 82 \u2197</a></blockquote>\n      </dl>\n    </div>\n    <div class=\"plate\" style=\"--st:var(--st-citrin)\">\n      <figure><span class=\"pbox\"><span class=\"cr\" style=\"aspect-ratio:1.115\"><img src=\"https://images.sourcelibrary.org/archived/69b52bf7a2d71b015aa975ab/270.jpg\" alt=\"Crowned figure inside a glass flask, hand-coloured plate\" loading=\"lazy\" style=\"width:111.11%;height:168.07%;left:-7.44%;top:-7.39%\"></span></span><figcaption>Crowned figure in a flask. Splendor Solis, 1598, image 270.</figcaption></figure>\n      <div class=\"deg\"><span class=\"n\">Third degree</span><h3>Citrinitas</h3><span class=\"plain\">Adept \u00b7 track or circle lead</span></div>\n      <dl>\n        <dt>Enter by</dt><dd>Sponsorship by two Adepts or a lead, countersigned by the coordinator.</dd>\n        <dt>The rite</dt><dd>The sponsor\u2019s three sentences are posted in #letters. The Adept checks one passage end to end, dedicated in their name.</dd>\n        <blockquote>\u201cThere are indeed three colors: black, white, and yellow.\u201d<a href=\"https://sourcelibrary.org/q/BhbmYbAoJrI07wWuHAZ\">Rosarium, scan 147 \u2197</a></blockquote>\n      </dl>\n    </div>\n    <div class=\"plate\" style=\"--st:var(--st-rubedo)\">\n      <figure><span class=\"pbox\"><span class=\"cr\" style=\"aspect-ratio:0.952\"><img src=\"https://images.sourcelibrary.org/archived/69bd9cd86120d54bd037157c/196.jpg\" alt=\"The risen figure stepping from the tomb with a banner, woodcut\" loading=\"lazy\" style=\"width:125.00%;height:142.45%;left:-12.50%;top:-22.22%\"></span></span><figcaption>The risen figure with banner. Rosarium, image 196.</figcaption></figure>\n      <div class=\"deg\"><span class=\"n\">Fourth degree</span><h3>Rubedo</h3><span class=\"plain\">Council \u00b7 at most eight, for one year</span></div>\n      <dl>\n        <dt>Enter by</dt><dd>Yearly rotation at C. Day. Each holder names a successor, as the Fama asks.</dd>\n        <dt>The rite</dt><dd>The outgoing holder says what they did and hands over the seat. The year\u2019s eight names go into a permanent colophon.</dd>\n        <blockquote>\u201c\u2026whiteness is turned into redness transparent like a ruby, and this is the elixir to the red.\u201d<a href=\"https://sourcelibrary.org/q/BhbmYbAoJrI07wWuH8k\">Rosarium, scan 34 \u2197</a></blockquote>\n      </dl>\n    </div>\n  </div>\n  </div>\n</section>\n\n<!-- 4 -->\n<section id=\"journey\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The volunteer\u2019s first six months</span><h2>Two people, from minute 0 to month 6</h2>\n  <p>Most signups are on a phone with two minutes and no plan to install anything. Some will lend their own Claude to a review shift if setup takes under five minutes and something visibly changes.</p></div>\n  <div class=\"legend\"><span><span class=\"rub\">\u2715</span> where people drop off</span><span><b>Bold</b>: what we send or show</span></div>\n  <div class=\"journey-scroll\">\n  <div class=\"journey\">\n    <div class=\"who\" style=\"border-bottom:1px solid var(--rule)\"></div>\n    <div class=\"t\">Minute 0</div><div class=\"t\">Hour 1</div><div class=\"t\">Day 1</div><div class=\"t\">Week 1</div><div class=\"t\">Month 1</div><div class=\"t\">Month 6</div>\n\n    <div class=\"who\">Reader-supporter<span>Phone, two minutes, came from an email</span></div>\n    <div><b>Welcome email.</b> One line of apology, one passage in their language with its translation, one button: \u201cRead this page.\u201d No account, no Discord.<span class=\"risk hi\">Deletes it as a newsletter</span></div>\n    <div><b>One question on the page:</b> \u201cDoes this sentence read right? Yes / Something\u2019s off.\u201d One tap is a contribution.<span class=\"risk\">Lands on a dense reader view with no task</span></div>\n    <div><b>An echo:</b> \u201cYour note on page 12 went to the reviewers. 41 people looked at pages yesterday.\u201d<span class=\"risk hi\">Silence after their action</span></div>\n    <div><b>The weekly Post</b> (EN/ES): one find, one quote, one name, one two-minute task. Discord link at the bottom.<span class=\"risk\">Unsubscribes; offer \u201cmonthly instead\u201d</span></div>\n    <div><b>The Nigredo letter</b> at the first threshold, e.g. 10 taps. Reading counts too.<span class=\"risk\">Taps too rare to reach it</span></div>\n    <div><b>\u201cYour name is in the colophon of [book].\u201d</b> A card to share. If they only read and share, that is enough.<span class=\"risk\">Drifts to monthly. Do not chase.</span></div>\n\n    <div class=\"who row2\">Claude donor<span>Desk, twenty minutes, uses claude.ai with the connector</span></div>\n    <div class=\"row2\"><b>Three numbered steps</b> with screenshots and a 60-second recording. About three minutes.<span class=\"risk hi\">Setup over five minutes; connector sign-in</span></div>\n    <div class=\"row2\"><b>First shift.</b> A receipt: pages checked, corrections proposed, one line before and after. The shift never asks them to read the language.<span class=\"risk\">No visible result</span></div>\n    <div class=\"row2\"><b>Bot post and email receipt:</b> \u201c3 OCR errors found; 2 confirmed by a second reviewer.\u201d<span class=\"risk\">Not on Discord; send it by email too</span></div>\n    <div class=\"row2\"><b>Second and third shifts</b> on different books, each with one sentence on why it matters. Tell them what a shift costs of their own usage.<span class=\"risk hi\">Repetition; worry about their Claude limits</span></div>\n    <div class=\"row2\"><b>The Albedo letter:</b> their agreement figure over N pages; harder books open.<span class=\"risk\">The quality bar feels opaque</span></div>\n    <div class=\"row2\"><b>\u201cYou checked 40% of this book. Would you lead its review?\u201d</b> Name in the colophon.<span class=\"risk hi\">Burnout, or it feels like unpaid labelling</span></div>\n  </div>\n  </div>\n</section>\n\n<!-- 5 -->\n<section id=\"year\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The year</span><h2>Weekly, monthly, seasonal, and one day a year</h2>\n  <p>Sessions run at 19:00 Amsterdam and 19:00 Bogot\u00e1, with a separate Spanish hour. Shown for 2027.</p></div>\n  <div class=\"year\">\n    <div class=\"wheel\"><svg id=\"wheel\" viewBox=\"0 0 440 440\" role=\"img\" aria-label=\"Year wheel for 2027: a weekly Post every Friday, a monthly colloquium on the first Thursday, four seasonal books at the equinoxes and solstices, and the convocation on C. Day, Thursday 24 June 2027.\"><circle cx=\"220\" cy=\"220\" r=\"196\" class=\"ring\"/><circle cx=\"220\" cy=\"220\" r=\"150\" class=\"ring\"/><circle cx=\"220\" cy=\"220\" r=\"116\" class=\"ring\"/><line x1=\"220\" y1=\"104\" x2=\"220\" y2=\"24\" class=\"tick\"/><text x=\"270.12128086124955\" y=\"16.068989104580425\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Jan</text><rect x=\"230.96525461711522\" y=\"66.29937701327185\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 235.46525461711522 70.79937701327185)\"/><line x1=\"279.0058294868441\" y1=\"120.12852215687664\" x2=\"319.6995049950125\" y2=\"51.2516408857571\" class=\"tick\"/><text x=\"366.88624868084594\" y=\"69.91858893097822\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Feb</text><rect x=\"298.36529697514294\" y=\"90.46663422421452\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 302.86529697514294 94.96663422421452)\"/><line x1=\"318.5787826171932\" y1=\"158.85898579748482\" x2=\"386.56414993939546\" y2=\"116.69276910609506\" class=\"tick\"/><text x=\"419.7218684219822\" y=\"155.10643118126103\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Mar</text><rect x=\"346.88375577163646\" y=\"143.12383873581723\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 351.38375577163646 147.62383873581723)\"/><line x1=\"335.97314622966735\" y1=\"217.50413269739823\" x2=\"415.9546263880586\" y2=\"215.78284490250044\" class=\"tick\"/><text x=\"424.9622156327973\" y=\"265.7218783832717\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Apr</text><rect x=\"365.46527529698363\" y=\"212.27258538456667\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 369.96527529698363 216.77258538456667)\"/><line x1=\"322.08141566093013\" y1=\"275.09432435977783\" x2=\"392.482391978813\" y2=\"313.09041012514183\" class=\"tick\"/><text x=\"375.65662227820513\" y=\"360.96459108918157\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">May</text><rect x=\"340.88882191279555\" y=\"297.82644374270785\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 345.38882191279555 302.32644374270785)\"/><line x1=\"279.8632373578389\" y1=\"319.3599155245164\" x2=\"321.1482286391072\" y2=\"387.88399519659674\" class=\"tick\"/><text x=\"282.309692047433\" y=\"420.5430185196036\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Jun</text><rect x=\"288.44090606630357\" y=\"346.5710655416621\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 292.94090606630357 351.0710655416621)\"/><line x1=\"222.99493906634743\" y1=\"335.9613312272193\" x2=\"225.06041428451806\" y2=\"415.9346631080602\" class=\"tick\"/><text x=\"175.16060775764285\" y=\"425.15708348320817\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Jul</text><rect x=\"219.37276603406994\" y=\"365.4499972765767\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 223.87276603406994 369.9499972765767)\"/><line x1=\"163.59236597539197\" y1=\"321.3616240188854\" x2=\"124.69054940669679\" y2=\"391.26619230777186\" class=\"tick\"/><text x=\"77.03758400982656\" y=\"373.8237550388515\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Aug</text><rect x=\"133.71393421890232\" y=\"341.24195578266614\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 138.21393421890232 345.74195578266614)\"/><line x1=\"119.87551314621027\" y1=\"278.5754823476963\" x2=\"50.824142902217346\" y2=\"318.97236672541794\" class=\"tick\"/><text x=\"18.66925843266776\" y=\"279.71542932901076\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Sep</text><rect x=\"84.74405219360173\" y=\"289.0042999643589\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 89.24405219360173 293.5042999643589)\"/><line x1=\"104.0096675960504\" y1=\"221.497594344701\" x2=\"24.01633490367138\" y2=\"222.53041803070172\" class=\"tick\"/><text x=\"15.438904413791676\" y=\"172.5157060432595\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Oct</text><rect x=\"66.11215057792313\" y=\"201.9622584953439\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 70.61215057792313 206.4622584953439)\"/><line x1=\"119.37506285136675\" y1=\"162.28845848676707\" x2=\"49.97855447299898\" y2=\"122.48739537419266\" class=\"tick\"/><text x=\"68.03475195785828\" y=\"75.06358846897601\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Nov</text><rect x=\"89.40723915482825\" y=\"134.2558269016028\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 93.90723915482825 138.7558269016028)\"/><line x1=\"160.99417051315584\" y1=\"120.12852215687668\" x2=\"120.30049500498744\" y2=\"51.251640885757155\" class=\"tick\"/><text x=\"159.41868909507212\" y=\"18.928110445441746\" class=\"lbl\" text-anchor=\"middle\" dominant-baseline=\"middle\">Dec</text><rect x=\"141.4336674760034\" y=\"85.06159159800836\" width=\"9\" height=\"9\" class=\"mo\" transform=\"rotate(45 145.9336674760034 89.56159159800836)\"/><circle cx=\"220\" cy=\"40\" r=\"2.2\" class=\"wk\"/><circle cx=\"241.6374480818835\" cy=\"41.30522995760677\" r=\"2.2\" class=\"wk\"/><circle cx=\"262.96109788107105\" cy=\"45.20199066106895\" r=\"2.2\" class=\"wk\"/><circle cx=\"283.6617019917469\" cy=\"51.6337691236333\" r=\"2.2\" class=\"wk\"/><circle cx=\"303.4390487625132\" cy=\"60.507288123855176\" r=\"2.2\" class=\"wk\"/><circle cx=\"322.00631613240114\" cy=\"71.69385896364022\" r=\"2.2\" class=\"wk\"/><circle cx=\"339.0942312836101\" cy=\"85.03124778317766\" r=\"2.2\" class=\"wk\"/><circle cx=\"354.45497578537993\" cy=\"100.32602836642843\" r=\"2.2\" class=\"wk\"/><circle cx=\"367.86577959443457\" cy=\"117.35638731547833\" r=\"2.2\" class=\"wk\"/><circle cx=\"379.13215178980545\" cy=\"135.8753409115596\" r=\"2.2\" class=\"wk\"/><circle cx=\"388.0907011881265\" cy=\"155.61431701003738\" r=\"2.2\" class=\"wk\"/><circle cx=\"394.61150593327125\" cy=\"176.28705002273156\" r=\"2.2\" class=\"wk\"/><circle cx=\"398.5999976952278\" cy=\"197.59373250037794\" r=\"2.2\" class=\"wk\"/><circle cx=\"399.9983331525142\" cy=\"219.22536310667604\" r=\"2.2\" class=\"wk\"/><circle cx=\"398.78623286813456\" cy=\"240.86822792719008\" r=\"2.2\" class=\"wk\"/><circle cx=\"394.98127539323104\" cy=\"262.20845012267375\" r=\"2.2\" class=\"wk\"/><circle cx=\"388.63864233317764\" cy=\"282.9365419452211\" r=\"2.2\" class=\"wk\"/><circle cx=\"379.8503180733088\" cy=\"302.75189310137876\" r=\"2.2\" class=\"wk\"/><circle cx=\"368.74375577030366\" cy=\"321.3671303694854\" r=\"2.2\" class=\"wk\"/><circle cx=\"355.48002895576155\" cy=\"338.5122852456488\" r=\"2.2\" class=\"wk\"/><circle cx=\"340.2514955584361\" cy=\"353.9387091768449\" r=\"2.2\" class=\"wk\"/><circle cx=\"323.2790082227785\" cy=\"367.42267960025436\" r=\"2.2\" class=\"wk\"/><circle cx=\"304.80871138129555\" cy=\"378.7686444920536\" r=\"2.2\" class=\"wk\"/><circle cx=\"285.1084715313582\" cy=\"387.8120583714124\" r=\"2.2\" class=\"wk\"/><circle cx=\"264.4639924865685\" cy=\"394.4217686303931\" r=\"2.2\" class=\"wk\"/><circle cx=\"243.17467194146454\" cy=\"398.5019175818722\" r=\"2.2\" class=\"wk\"/><circle cx=\"221.54925943996395\" cy=\"399.9933326409278\" r=\"2.2\" class=\"wk\"/><circle cx=\"199.901378718095\" cy=\"398.87438447851207\" r=\"2.2\" class=\"wk\"/><circle cx=\"178.54497935848983\" cy=\"395.16130070198716\" r=\"2.2\" class=\"wk\"/><circle cx=\"157.789783719268\" cy=\"388.90793051335555\" r=\"2.2\" class=\"wk\"/><circle cx=\"137.93679516847743\" cy=\"380.20496375824183\" r=\"2.2\" class=\"wk\"/><circle cx=\"119.27393276616819\" cy=\"369.17861569141064\" r=\"2.2\" class=\"wk\"/><circle cx=\"102.07185570236467\" cy=\"355.98879653308245\" r=\"2.2\" class=\"wk\"/><circle cx=\"86.5800380472528\" cy=\"340.82679236215574\" r=\"2.2\" class=\"wk\"/><circle cx=\"73.02315073973517\" cy=\"323.912490979311\" r=\"2.2\" class=\"wk\"/><circle cx=\"61.597803284763586\" cy=\"305.49119297206903\" r=\"2.2\" class=\"wk\"/><circle cx=\"52.46969241316373\" cy=\"285.83005422950845\" r=\"2.2\" class=\"wk\"/><circle cx=\"45.77119905566843\" cy=\"265.2142114992675\" r=\"2.2\" class=\"wk\"/><circle cx=\"41.59946848117818\" cy=\"243.94264717615533\" r=\"2.2\" class=\"wk\"/><circle cx=\"40.01500144214717\" cy=\"222.32385329350157\" r=\"2.2\" class=\"wk\"/><circle cx=\"41.04077675908866\" cy=\"200.6713576004508\" r=\"2.2\" class=\"wk\"/><circle cx=\"44.6619180689643\" cy=\"179.29917660850813\" r=\"2.2\" class=\"wk\"/><circle cx=\"50.825909570458805\" cy=\"158.51726154978604\" r=\"2.2\" class=\"wk\"/><circle cx=\"59.44335763728131\" cy=\"138.62700329218518\" r=\"2.2\" class=\"wk\"/><circle cx=\"70.38928725415451\" cy=\"119.9168614017321\" r=\"2.2\" class=\"wk\"/><circle cx=\"83.50495447385873\" cy=\"102.65818074183176\" r=\"2.2\" class=\"wk\"/><circle cx=\"98.60014861006978\" cy=\"87.10125627944086\" r=\"2.2\" class=\"wk\"/><circle cx=\"115.45595077831578\" cy=\"73.47170316852083\" r=\"2.2\" class=\"wk\"/><circle cx=\"133.82790877915798\" cy=\"61.9671847538402\" r=\"2.2\" class=\"wk\"/><circle cx=\"153.44958227967885\" cy=\"52.754545947428625\" r=\"2.2\" class=\"wk\"/><circle cx=\"174.03640687908631\" cy=\"45.96739355105004\" r=\"2.2\" class=\"wk\"/><circle cx=\"195.28982101961228\" cy=\"41.70415861619992\" r=\"2.2\" class=\"wk\"/><circle cx=\"216.90159589194965\" cy=\"40.026668942359066\" r=\"2.2\" class=\"wk\"/><circle cx=\"349.55536053793196\" cy=\"189.92661382739766\" r=\"7\" class=\"se\"/><circle cx=\"246.15749434254568\" cy=\"350.4023983280971\" r=\"7\" class=\"se\"/><circle cx=\"88.50588049909871\" cy=\"239.95736797983878\" r=\"7\" class=\"se\"/><circle cx=\"194.96584759084845\" cy=\"89.37729441955594\" r=\"7\" class=\"se\"/><polygon points=\"244.1,372.2 247.0,379.2 254.5,379.8 248.8,384.8 250.5,392.1 244.1,388.2 237.6,392.1 239.3,384.8 233.6,379.8 241.1,379.2\" class=\"cday\"/><text x=\"227.41352611662847\" y=\"315.0169067652737\" class=\"ctext\" text-anchor=\"middle\">C. Day</text><text x=\"220\" y=\"214\" class=\"center\" text-anchor=\"middle\">2027</text><text x=\"220\" y=\"236\" class=\"center2\" text-anchor=\"middle\">52 Posts \u00b7 12 colloquia</text><text x=\"220\" y=\"252\" class=\"center2\" text-anchor=\"middle\">4 books \u00b7 1 convocation</text></svg></div>\n    <div class=\"rhythms\">\n      <div class=\"rhythm\"><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"3\" class=\"wk\" style=\"fill:var(--ink-2)\"/></svg><div><h3>Weekly \u00b7 The Post, on Fridays</h3><p>One find, pages checked this week, three names, one task, in English and Spanish. Plus an open shift hour in each time slot, where a lead answers questions. No attendance taken.</p></div></div>\n      <div class=\"rhythm\"><svg viewBox=\"0 0 22 22\"><rect x=\"6\" y=\"6\" width=\"10\" height=\"10\" transform=\"rotate(45 11 11)\" style=\"fill:var(--ink)\"/></svg><div><h3>Monthly \u00b7 Colloquium, first Thursday</h3><p>45 minutes: one member presents one find, one lead reports, one open question. The month\u2019s best five letters are bound as a citable page, and the thank-you post names who did what.</p></div></div>\n      <div class=\"rhythm\"><svg viewBox=\"0 0 22 22\"><circle cx=\"11\" cy=\"11\" r=\"7\" style=\"fill:var(--paper);stroke:var(--ink);stroke-width:1.5\"/></svg><div><h3>Seasonal \u00b7 The Book of the Season</h3><p>One book chosen by vote at each equinox and solstice. Every track works on it for three months; its colophon is posted at the next turn. Four finished books a year.</p></div></div>\n      <div class=\"rhythm\"><svg viewBox=\"0 0 22 22\"><path d=\"M11 1.5l2.6 6.3 6.8.5-5.2 4.4 1.6 6.6L11 15.7 5.2 19.3l1.6-6.6L1.6 8.3l6.8-.5z\" style=\"fill:var(--rubric)\"/></svg><div><h3 class=\"rub\">Yearly \u00b7 Convocation on C. Day</h3><p>The Fama\u2019s brothers met once a year \u201con C. Day\u201d or sent the cause of their absence. Proposal: the Thursday nearest 21 June, which is <b>24 June 2027</b>. Ninety minutes online, and in person at the Embassy of the Free Mind for whoever can come. The year\u2019s colophon is read, the council seats rotate, budget and decisions are shown in full, absentees\u2019 letters are read.</p></div></div>\n    </div>\n  </div>\n  <div class=\"first-month\">\n    <h3>The first month: answering the 1,438</h3>\n    <div class=\"weeks\">\n      <div><span class=\"w\">Week 1</span>One email to all 1,438 in English or Spanish: thanks, one first task matched to what they wrote, a one-click stop. Sent from Derek\u2019s address in batches; read the first batch\u2019s open rate before sending the rest.</div>\n      <div><span class=\"w\">Week 1</span>The Discord with its channels, a pinned code of conduct, and a bot that posts finished shifts and newly readable books. An automatic welcome for every new signup.</div>\n      <div><span class=\"w\">Weeks 2\u20134</span>The first Post goes out on a Friday. A weekly open hour on Discord. The Spanish reading circle opens to the roughly 345 Spanish speakers.</div>\n      <div><span class=\"w\">End of month</span>The first monthly thank-you with names and results. The first email\u2019s replies give the coordinator the people to ask to lead.</div>\n    </div>\n  </div>\n</section>\n\n<!-- 6 -->\n<section id=\"mechanics\">\n  <div class=\"sh\"><span class=\"label\">\u2767 Borrowed from history</span><h2>Eight mechanics that worked before, and how they failed</h2>\n  <p>Most precedents are from secondary summaries; figures are as those sources give them.</p></div>\n  <div class=\"mechs\">\n    <div class=\"mech\"><h3>An open letter of application</h3><p>Anyone may write a short letter saying what they will give and why. With consent, letters are shelved next to our Fama.</p><p class=\"prec\"><i>Precedent:</i> Haslmayr\u2019s printed Answer to the Brotherhood, 1612, and the replies to the Fama after 1614.</p><p class=\"risk\">Risk: public petitions invite trolling. Haslmayr was sent to the galleys. Keep it consent-based, with a private option.</p></div>\n    <div class=\"mech\"><h3>Correspondence as membership</h3><p>The first standing is one letter to a named correspondent. A reply makes you a Correspondent.</p><p class=\"prec\"><i>Precedent:</i> the Hartlib circle, a definable centre with an \u201calmost infinitely extendable periphery\u201d.</p><p class=\"risk\">Risk: Hartlib\u2019s network left no institution, and correspondents burn out.</p></div>\n    <div class=\"mech\"><h3>Mentored first shift</h3><p>A newcomer\u2019s first review shift is paired with a mentor. After some shifts, they may mentor.</p><p class=\"prec\"><i>Precedent:</i> Black Rock Rangers: training, then a mentored evaluation shift.</p><p class=\"risk\">Risk: the Rangers close intake when demand outruns mentors. Plan capacity and keep an honest waitlist.</p></div>\n    <div class=\"mech\"><h3>A forum from day one</h3><p>Open a place to discuss finds at once, because email will swamp the team.</p><p class=\"prec\"><i>Precedent:</i> Galaxy Zoo added a forum two weeks in; volunteers found Hanny\u2019s Voorwerp there.</p><p class=\"risk\">Risk: moderation load. The Galaxy Zoo forum was archived after seven years.</p></div>\n    <div class=\"mech\"><h3>Winners write next year\u2019s hunt</h3><p>Each year a cohort of degree-holders designs the next year\u2019s gates and convocation.</p><p class=\"prec\"><i>Precedent:</i> MIT Mystery Hunt, since 1981; the winning team writes the next one.</p><p class=\"risk\">Risk: quality swings unless a handbook carries over.</p></div>\n    <div class=\"mech\"><h3>A low-bar tally, no punishment</h3><p>A \u201clight kept\u201d count of one checked page, with rest days built in.</p><p class=\"prec\"><i>Precedent:</i> Duolingo decoupled the streak from the daily goal; day-14 retention rose 3.3%.</p><p class=\"risk\">Risk: rewards speed over care. Count checked pages that pass a quality screen.</p></div>\n    <div class=\"mech\"><h3>One convocation on a fixed date</h3><p>A single online gathering a year, with a year-in-review and degree announcements.</p><p class=\"prec\"><i>Precedent:</i> the World Esperanto Congress since 1905, moving city each year.</p><p class=\"risk\">Risk: Esperanto\u2019s 1936 schism. Keep it cheap, online, and its decisions public.</p></div>\n    <div class=\"mech\"><h3>Published principles</h3><p>A short list (open, no oaths, decisions in public), read aloud at the convocation.</p><p class=\"prec\"><i>Precedent:</i> Burning Man\u2019s Ten Principles, 2004.</p><p class=\"risk\">Risk: principles are cited against the organisers when practice drifts. That is also their use.</p></div>\n  </div>\n</section>\n\n<!-- 7 -->\n<section id=\"wild\">\n  <div class=\"sh\"><span class=\"label\">\u2767 Wild ideas</span><h2>Fifteen to argue about</h2>\n  <p>Unranked. Each carries its main risk.</p></div>\n  <div class=\"wild\">\n    <div class=\"idea\"><span class=\"num\">1</span><h3>Open letters of application</h3><p>Anyone publishes what they would bring; the best are answered publicly.</p><span class=\"rk\">Exhibitionism</span></div>\n    <div class=\"idea\"><span class=\"num\">2</span><h3>First find as a broadside</h3><p>A first real find, typeset as a one-page broadside with their name.</p><span class=\"rk\">Effort</span></div>\n    <div class=\"idea\"><span class=\"num\">3</span><h3>Dedicated translations</h3><p>A dedication line chosen by whoever did most of the checking.</p><span class=\"rk\">Clutter</span></div>\n    <div class=\"idea\"><span class=\"num\">4</span><h3>Puzzles in the books</h3><p>A seasonal hunt whose clues point to pages; solving one means checking the page.</p><span class=\"rk\">Gimmick</span></div>\n    <div class=\"idea\"><span class=\"num\">5</span><h3>Name in the colophon</h3><p>Of every book you touched, permanently, with date and degree.</p><span class=\"rk\">None</span></div>\n    <div class=\"idea\"><span class=\"num\">6</span><h3>A seal from the library</h3><p>Each member picks a public-domain plate as their emblem.</p><span class=\"rk\">Copyright</span></div>\n    <div class=\"idea\"><span class=\"num\">7</span><h3>Post CXX annos patebo</h3><p>Letters sealed until 2034, the Fama\u2019s 420th year.</p><span class=\"rk\">Forgotten</span></div>\n    <div class=\"idea\"><span class=\"num\">8</span><h3>Correspondent pairs</h3><p>Each newcomer paired with a member in another country for a month.</p><span class=\"rk\">Dropout</span></div>\n    <div class=\"idea\"><span class=\"num\">9</span><h3>A Spanish Fama</h3><p>The Spanish circle makes its own edition of the Fama and Confessio.</p><span class=\"rk\">Quality</span></div>\n    <div class=\"idea\"><span class=\"num\">10</span><h3>Ask the College</h3><p>Wikipedia editors post sourcing questions; members answer with citations.</p><span class=\"rk\">Policy</span></div>\n    <div class=\"idea\"><span class=\"num\">11</span><h3>A vacant seat</h3><p>One of the eight council seats always left for the member we have not met.</p><span class=\"rk\">Precious</span></div>\n    <div class=\"idea\"><span class=\"num\">12</span><h3>The Projection, live</h3><p>When a book\u2019s last page is reviewed, its colophon appears live.</p><span class=\"rk\">Anticlimax</span></div>\n    <div class=\"idea\"><span class=\"num\">13</span><h3>A library card by post</h3><p>Albedo members get a printed card mailed from Amsterdam.</p><span class=\"rk\">Cost</span></div>\n    <div class=\"idea\"><span class=\"num\">14</span><h3>Readers\u2019 marginalia</h3><p>Signed public notes on a page, shown as a faint annotation.</p><span class=\"rk\">Moderation</span></div>\n    <div class=\"idea\"><span class=\"num\">15</span><h3>Chymical Wedding week</h3><p>Easter week: seven days, one chapter and one task a day.</p><span class=\"rk\">Overload</span></div>\n  </div>\n</section>\n\n<!-- 8 -->\n<section id=\"premortem\">\n  <div class=\"sh\"><span class=\"label\">\u2767 Pre-mortem</span><h2>It is a year from now and this failed. Here is how.</h2></div>\n  <div class=\"pm\">\n    <div class=\"fail\"><h3>The first email lands as a stranger\u2019s</h3><p>Three months late, generic, from an unknown sender. Under 20% open it, and the first impression is permanent.</p><p class=\"warn\"><span>Early warning</span>Open rate on the first batch below 30%, or spam complaints above 0.1%.</p></div>\n    <div class=\"fail\"><h3>Silence after the first action</h3><p>People tap or run a shift, nothing echoes back for a week, and they conclude it did not count.</p><p class=\"warn\"><span>Early warning</span>Under 25% of first-time contributors return within 14 days.</p></div>\n    <div class=\"fail\"><h3>The metaphor turns cultish</h3><p>A vocal member pushes spiritual readings; librarians and academics leave quietly; a journalist calls it a secret society.</p><p class=\"warn\"><span>Early warning</span>\u201cInitiate\u201d and \u201cadept\u201d used without irony; skilled sign-ups stop; someone asks \u201cdo I have to believe this?\u201d</p></div>\n    <div class=\"fail\"><h3>The coordinator burns out</h3><p>Everything routes through one person. The weekly Post slips to monthly, then stops.</p><p class=\"warn\"><span>Early warning</span>The Post misses two weeks running; Discord questions sit unanswered past 48 hours.</p></div>\n    <div class=\"fail\"><h3>The Claude donor feels used</h3><p>Shifts repeat, the result is a number, their own limits get hit. It reads as unpaid labelling in costume.</p><p class=\"warn\"><span>Early warning</span>Median shifts per donor stays at one; donors ask \u201cwhat happens to my work?\u201d</p></div>\n    <div class=\"fail\"><h3>Spanish is a translation, not a community</h3><p>Emails go out in Spanish, but Discord, colloquia and leads stay English. A quarter of the members drift away.</p><p class=\"warn\"><span>Early warning</span>No Spanish-speaking lead by month two; the Spanish channel under one post a day.</p></div>\n  </div>\n</section>\n\n<!-- 9 -->\n<section id=\"covenant\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The covenant</span><h2>Six articles, kept from the Fama, the sixth reversed</h2></div>\n  <div class=\"broadside\">\n    <div class=\"head\">\n      <span class=\"sc\">Of the Praiseworthy Order</span>\n      <h3>The Articles of the College</h3>\n      <p>Upon these six articles they pledged themselves to one another.</p>\n    </div>\n    <div class=\"art\"><span class=\"num\">1</span><p class=\"orig\">\u201cNone of them should profess any other calling than to cure the sick, and that for free.\u201d</p><p class=\"ours\">We serve freely. No fees, and no degree can be bought.</p></div>\n    <div class=\"art\"><span class=\"num\">2</span><p class=\"orig\">\u201cNo one shall be forced\u2026 to wear a specific garment, but rather should follow the custom of the country.\u201d</p><p class=\"ours\">Come as you are. No jargon or belief required.</p></div>\n    <div class=\"art\"><span class=\"num\">3</span><p class=\"orig\">\u201cEvery brother should present himself every year on C. Day\u2026 or send the cause of his absence.\u201d</p><p class=\"ours\">One gathering a year, online and in Amsterdam. Absence is fine; send word.</p></div>\n    <div class=\"art\"><span class=\"num\">4</span><p class=\"orig\">\u201cEvery brother should look about for a fit person who might succeed him.\u201d</p><p class=\"ours\">Every Adept trains a successor.</p></div>\n    <div class=\"art\"><span class=\"num\">5</span><p class=\"orig\">\u201cThe word R. C. should be their seal, watchword, and character.\u201d</p><p class=\"ours\">Each degree has its seal, a plate from the library.</p></div>\n    <div class=\"art rev\"><span class=\"num\">6</span><p class=\"orig\">\u201cThe Brotherhood should remain secret for one hundred years.\u201d</p><p class=\"ours\">This one we reverse. Every degree, what it takes, and who holds it is public. The mysteries are in the books, not in the rules.</p></div>\n    <div class=\"foot\">\n      <p class=\"guard\">No oaths, no fees, no secrecy about money or decisions. Anyone can step back at any degree. Nobody is asked to believe anything.</p>\n      <p>Johann Valentin Andreae (attr.), <i>The Fame of the Brotherhood</i>, 1614, pp. 28\u201329 [scans 34\u201335], trans. Source Library 2026. <a href=\"https://sourcelibrary.org/q/u0usva8gbJH0SVDTMnFjKyHEMV\">sourcelibrary.org/q/u0usva8gbJH0SVDTMnFjKyHEMV</a> \u00b7 <a href=\"https://sourcelibrary.org/book/fama-fraternitatis-1615-danzig-attr\">the book</a></p>\n    </div>\n  </div>\n</section>\n\n<!-- 10 -->\n<section id=\"ambassadors\">\n  <div class=\"sh\"><span class=\"label\">\u2767 The outer office</span><h2>Ambassadors: people who carry the library to an audience</h2>\n  <p>The degrees face inward: work on the books. Ambassadors face outward. They already have listeners, viewers or students, and they bring them to the sources. It is an office, not a degree, so an ambassador can hold either, both, or no degree. The first candidate is a podcaster and video maker. He wrote on 16 October asking to feature the library and to adapt texts into videos, audiobooks and lectures, with full credit.</p></div>\n  <div class=\"mechs\">\n    <div class=\"mech\"><h3>What an ambassador gives</h3><p>At least one piece a season, such as an episode, video, reading or class, built on a book we hold. It links to the book or the quoted page, not just the homepage.</p><p class=\"prec\"><i>Precedent:</i> the Fama itself, a manifesto that spread through printers and readers who republished it, not through members.</p><p class=\"risk\">Risk: we count posts and learn nothing. Count the readers who arrive and stay on a book.</p></div>\n    <div class=\"mech\"><h3>What the library gives</h3><p>A kit: shortlinks for the passages they quote, full-resolution plates, a one-line citation, and a plain note on the licence. They also get a week\u2019s early look at new translations in their area, one named contact, and their name on an Ambassadors page.</p><p class=\"prec\"><i>Precedent:</i> museum and publisher creator programmes, where early access and assets matter more than money.</p><p class=\"risk\">Risk: a kit nobody maintains goes stale. Build it from what the site already serves: shortlinks, quote pages, IIIF images.</p></div>\n    <div class=\"mech\"><h3>Their own links, their own count</h3><p>Each ambassador gets a short code added to their shortlinks. Once a month they see how many readers their links brought, and which books those readers opened.</p><p class=\"prec\"><i>Precedent:</i> affiliate links, without the commission.</p><p class=\"risk\">Risk: the number becomes a league table. Show each person their own figures only.</p></div>\n    <div class=\"mech\"><h3>Adaptations come home</h3><p>When an ambassador records or films a text, the book page links to it, for example with \u201cListen: read by \u2026\u201d. The audience reaches the source, and the source page points back to the adaptation.</p><p class=\"prec\"><i>Precedent:</i> LibriVox readings linked from Project Gutenberg texts.</p><p class=\"risk\">Risk: a weak recording sits beside the book. Link only what the coordinator has played through.</p></div>\n    <div class=\"mech\"><h3>The licence, said plainly</h3><p>The originals are public domain. Our translations are CC BY-SA 4.0. Anyone may adapt them, for money or not, if they credit the library and release the adapted text, such as an audiobook script, under the same licence. There is no exclusive deal.</p><p class=\"prec\"><i>Precedent:</i> Wikipedia\u2019s share-alike reuse by broadcasters and publishers.</p><p class=\"risk\">Risk: share-alike surprises someone after they have recorded. Explain it in the first conversation, not in a footnote.</p></div>\n    <div class=\"mech\"><h3>Corrections flow back</h3><p>Audiences that read closely find errors. An ambassador forwards them to one address, and a fixed page credits the person who found it.</p><p class=\"prec\"><i>Precedent:</i> errata lists in early modern editions, which thanked readers by name.</p><p class=\"risk\">Risk: an ambassador\u2019s claim about a text reads as ours. Ambassadors speak for themselves and cite the page, so listeners can check it.</p></div>\n  </div>\n  <p class=\"sub\" style=\"margin-top:20px\"><b>First step:</b> one pilot with the first candidate. He adapts one emblem book into an episode and a reading, using his own code. We link the reading from the book page, and after a month we look at what arrived.</p>\n</section>\n\n<section id=\"decisions\">\n  <div class=\"sh\"><span class=\"label\">\u2767 Decisions for Derek</span><h2>Seven questions, each with a default</h2>\n  <p>Answering \u201cdefaults\u201d to all seven is enough to start the first month.</p></div>\n  <div class=\"decisions\">\n    <div class=\"dec\"><span class=\"num\">1</span><div><h3>The world</h3><p class=\"def\"><b>Default</b>The Invisible College, with the alchemical degrees inside under plain subtitles, and scriptorium words for tasks.</p></div><p class=\"alt\"><b>Or</b>The Order of the Work alone (stronger identity, more cult risk), or the Scriptorium alone (respectable, less pull).</p></div>\n    <div class=\"dec\"><span class=\"num\">2</span><div><h3>The first email to the 1,438</h3><p class=\"def\"><b>Default</b>From Derek\u2019s address, in English and Spanish, subject line naming a book. Derek approves both texts; sent in batches.</p></div><p class=\"alt\"><b>Or</b>From a coordinator or a project address, which reads more like a newsletter.</p></div>\n    <div class=\"dec\"><span class=\"num\">3</span><div><h3>C. Day</h3><p class=\"def\"><b>Default</b>The Thursday nearest 21 June: 24 June 2027. Online, and at the Embassy of the Free Mind if the Embassy agrees.</p></div><p class=\"alt\"><b>Or</b>Corpus Christi itself (Thursday 27 May 2027), moveable each year and read by some as a Catholic observance.</p></div>\n    <div class=\"dec\"><span class=\"num\">4</span><div><h3>Names and credit</h3><p class=\"def\"><b>Default</b>Names public by default in colophons and on degree lists, with a one-click opt-out.</p></div><p class=\"alt\"><b>Or</b>Opt-in only: safer for privacy, fewer names and less of the reason to share.</p></div>\n    <div class=\"dec\"><span class=\"num\">5</span><div><h3>Where the College lives</h3><p class=\"def\"><b>Default</b>Email is the main channel for readers; Discord is home for those who want it, never required.</p></div><p class=\"alt\"><b>Or</b>A forum instead of Discord, slower but searchable and archivable.</p></div>\n    <div class=\"dec\"><span class=\"num\">6</span><div><h3>Who runs it</h3><p class=\"def\"><b>Default</b>A volunteer coordinator first, picked from replies to the first email. A paid part-time role only if activity outgrows it.</p></div><p class=\"alt\"><b>Or</b>A paid community lead from the start.</p></div>\n    <div class=\"dec\"><span class=\"num\">7</span><div><h3>Ambassadors</h3><p class=\"def\"><b>Default</b>Invite only for the first season: the podcaster as a pilot, then five to ten creators we approach. A kit, early access, their own link code and credit. No money changes hands, and the licence stays CC BY-SA.</p></div><p class=\"alt\"><b>Or</b>An open application from the start, which brings more reach but needs vetting, or paid partnerships, which bring commitments we can enforce and also cost money.</p></div>\n  </div>\n</section>\n\n<footer class=\"colophon\">\n  <p>Sources: precedent research (secondary, mostly encyclopaedia summaries), library passages via Source Library shortlinks, and the volunteer plan of 21 October 2026.</p>\n  <p>Plates from the Rosarium philosophorum (1550) and the Splendor Solis (1598), public domain, as held by Source Library.</p>\n</footer>\n</div>\n\n\n\n</body></html>";
